import fs from 'fs';
import path from 'path';
import { escapeGradleString, normalizeJvmTarget } from '../utils.js';
import { log } from '../../core/logger.js';
export function writeAppBuildGradle(config, projectDir) {
    const build = config.build;
    const signing = config.signing;
    const normalizedJvmTarget = normalizeJvmTarget(build.jvmTarget);
    const storeFilePath = signing?.storeFile.replace(/\\/g, '/');
    const signingBlock = signing ? `
    signingConfigs {
        create("release") {
            storeFile       = file("${escapeGradleString(storeFilePath ?? '')}")
            storePassword   = "${escapeGradleString(signing.storePassword)}"
            keyAlias        = "${escapeGradleString(signing.keyAlias)}"
            keyPassword     = "${escapeGradleString(signing.keyPassword)}"
            enableV1Signing = ${signing.v1SigningEnabled ?? true}
            enableV2Signing = ${signing.v2SigningEnabled ?? true}
            enableV3Signing = ${signing.v3SigningEnabled ?? true}
            enableV4Signing = ${signing.v4SigningEnabled ?? false}
        }
    }` : '';
    const releaseSigningRef = signing ? `            signingConfig = signingConfigs.getByName("release")` : `            // No signing config provided - produces unsigned release APK`;
    const extraBuildConfig = Object.entries(build.extraProperties ?? {}).map(([key, value]) => `        buildConfigField("String", "${escapeGradleString(key)}", "\\"${escapeGradleString(value)}\\"")`).join('\n');
    const gradle = `plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
}

android {
    namespace         = "${escapeGradleString(config.appId)}"
    compileSdk        = ${config.compileSdk}
    buildToolsVersion = "${escapeGradleString(config.buildToolsVersion ?? '')}"
${signingBlock}

    defaultConfig {
        applicationId = "${escapeGradleString(config.appId)}"
        minSdk        = ${config.minSdk}
        targetSdk     = ${config.targetSdk}
        versionCode   = ${config.versionCode}
        versionName   = "${escapeGradleString(config.versionName ?? '')}"
${extraBuildConfig ? `${extraBuildConfig}\n` : ''}    }

    buildTypes {
        debug {
            applicationIdSuffix = ".debug"
            isDebuggable        = true
        }

        release {
            isMinifyEnabled   = ${build.minifyEnabled}
            isShrinkResources = ${build.shrinkResources}
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
${releaseSigningRef}
        }
    }

    buildFeatures {
        buildConfig = true
    }

    compileOptions {
        sourceCompatibility = JavaVersion.toVersion("${normalizedJvmTarget}")
        targetCompatibility = JavaVersion.toVersion("${normalizedJvmTarget}")
    }

    kotlinOptions {
        jvmTarget = "${normalizedJvmTarget}"
    }

    applicationVariants.all {
        val variant = this
        variant.outputs.all {
            val output = this as com.android.build.gradle.internal.api.BaseVariantOutputImpl
            output.outputFileName = "${escapeGradleString(config.artifact ?? 'app')}-\${variant.buildType.name}.apk"
        }
    }
}

dependencies {
    implementation("androidx.appcompat:appcompat:1.7.0")
    implementation("androidx.core:core-ktx:1.15.0")
    implementation("androidx.webkit:webkit:1.13.0")
}`;
    fs.mkdirSync(path.join(projectDir, 'app'), { recursive: true });
    fs.writeFileSync(path.join(projectDir, 'app/build.gradle.kts'), gradle);
    log.dim('  app/build.gradle.kts');
}
export function writeRootBuildGradle(config, projectDirectory) {
    const build = config.build;
    fs.writeFileSync(path.join(projectDirectory, 'build.gradle.kts'), `plugins {
    id("com.android.application") version "${escapeGradleString(build.agpVersion ?? '')}" apply false
    id("org.jetbrains.kotlin.android") version "${escapeGradleString(build.kotlinVersion ?? '')}" apply false
}`);
    log.dim('  build.gradle.kts (root)');
}
export function writeSettingsGradle(config, projectDirectory) {
    fs.writeFileSync(path.join(projectDirectory, 'settings.gradle.kts'), `pluginManagement {
    repositories {
        google {
            content {
                includeGroupByRegex("com\\\\.android.*")
                includeGroupByRegex("com\\\\.google.*")
                includeGroupByRegex("androidx.*")
            }
        }
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "${escapeGradleString(config.appName)}"
include(":app")`);
    log.dim('  settings.gradle.kts');
}
export function writeGradleProperties(config, projectDirectory) {
    const extra = Object.entries(config.build?.extraProperties ?? {}).map(([key, value]) => `${key}=${value}`).join('\n');
    fs.writeFileSync(path.join(projectDirectory, 'gradle.properties'), `org.gradle.jvmargs=-Xmx4096m -Dfile.encoding=UTF-8
org.gradle.parallel=true
org.gradle.caching=true
org.gradle.configureondemand=true
android.useAndroidX=true
android.enableJetifier=true
kotlin.code.style=official${extra ? `\n${extra}` : ''}`);
    log.dim('  gradle.properties');
}
export function writeGradleWrapperProps(projectDirectory) {
    const directory = path.join(projectDirectory, 'gradle/wrapper');
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(path.join(directory, 'gradle-wrapper.properties'), `distributionBase=GRADLE_USER_HOME
distributionPath=wrapper/dists
distributionUrl=https\\://services.gradle.org/distributions/gradle-8.10.2-bin.zip
networkTimeout=10000
validateDistributionUrl=true
zipStoreBase=GRADLE_USER_HOME
zipStorePath=wrapper/dists`);
    log.dim('  gradle-wrapper.properties');
}
